#!/usr/bin/env python3

"""Interpreter for a tiny integer expression language."""

_KEYWORDS = frozenset({
    "False", "None", "True", "and", "as", "assert", "async", "await",
    "break", "class", "continue", "def", "del", "elif", "else", "except",
    "finally", "for", "from", "global", "if", "import", "in", "is",
    "lambda", "nonlocal", "not", "or", "pass", "raise", "return",
    "try", "while", "with", "yield",
})


class _InvalidProgram(Exception):
    pass


def _is_name_start(ch):
    return (
        "A" <= ch <= "Z"
        or "a" <= ch <= "z"
        or ch == "_"
    )


def _is_name_part(ch):
    return _is_name_start(ch) or "0" <= ch <= "9"


def _decimal_value(text):
    value = 0
    for ch in text:
        value = value * 10 + (ord(ch) - ord("0"))
    return value


def _tokenize(src):
    tokens = []
    index = 0
    length = len(src)

    while index < length:
        ch = src[index]

        if ch in " \t\n":
            index += 1
            continue

        if "0" <= ch <= "9":
            start = index
            index += 1
            while index < length and "0" <= src[index] <= "9":
                index += 1
            tokens.append(("INT", _decimal_value(src[start:index])))
            continue

        if _is_name_start(ch):
            start = index
            index += 1
            while index < length and _is_name_part(src[index]):
                index += 1
            name = src[start:index]
            if name in _KEYWORDS:
                raise _InvalidProgram
            tokens.append(("NAME", name))
            continue

        if ch == "*":
            if index + 1 < length and src[index + 1] == "*":
                tokens.append(("**", None))
                index += 2
            else:
                tokens.append(("*", None))
                index += 1
            continue

        if ch == "/":
            if index + 1 < length and src[index + 1] == "/":
                tokens.append(("//", None))
                index += 2
            else:
                raise _InvalidProgram
            continue

        if ch in "+-%()=;":
            tokens.append((ch, None))
            index += 1
            continue

        raise _InvalidProgram

    tokens.append(("EOF", None))
    return tokens


class _Parser:
    def __init__(self, tokens):
        self._tokens = tokens
        self._position = 0
        self._environment = {}

    def _kind(self):
        return self._tokens[self._position][0]

    def _value(self):
        return self._tokens[self._position][1]

    def _advance(self):
        token = self._tokens[self._position]
        self._position += 1
        return token

    def _accept(self, kind):
        if self._kind() == kind:
            self._advance()
            return True
        return False

    def _require(self, kind):
        if self._kind() != kind:
            raise _InvalidProgram
        return self._advance()

    def _primary(self):
        kind = self._kind()

        if kind == "INT":
            return self._advance()[1]

        if kind == "NAME":
            name = self._advance()[1]
            if name not in self._environment:
                raise _InvalidProgram
            return self._environment[name]

        if self._accept("("):
            if self._kind() == ")":
                raise _InvalidProgram
            value = self._expression()
            self._require(")")
            return value

        raise _InvalidProgram

    def _power(self):
        left = self._primary()
        if self._accept("**"):
            exponent = self._unary()
            if exponent < 0:
                raise _InvalidProgram
            return left ** exponent
        return left

    def _unary(self):
        if self._accept("-"):
            return -self._unary()
        return self._power()

    def _multiplicative(self):
        value = self._unary()

        while self._kind() in ("*", "//", "%"):
            operator = self._advance()[0]
            right = self._unary()

            if operator == "*":
                value = value * right
            elif operator == "//":
                if right == 0:
                    raise _InvalidProgram
                value = value // right
            else:
                if right == 0:
                    raise _InvalidProgram
                value = value % right

        return value

    def _additive(self):
        value = self._multiplicative()

        while self._kind() in ("+", "-"):
            operator = self._advance()[0]
            right = self._multiplicative()
            if operator == "+":
                value = value + right
            else:
                value = value - right

        return value

    def _expression(self):
        return self._additive()

    def _statement(self):
        if (
            self._kind() == "NAME"
            and self._tokens[self._position + 1][0] == "="
        ):
            name = self._advance()[1]
            self._advance()
            value = self._expression()
            self._environment[name] = value
        else:
            self._expression()

    def _program(self):
        while True:
            while self._accept(";"):
                pass

            if self._kind() == "EOF":
                return dict(self._environment)

            self._statement()

            if self._kind() == "EOF":
                return dict(self._environment)
            if self._kind() != ";":
                raise _InvalidProgram


def run_program(src: str) -> dict | None:
    """Execute *src* and return its final environment, or None if invalid."""
    if not isinstance(src, str):
        return None

    try:
        return _Parser(_tokenize(src))._program()
    except Exception:
        return None

#!/usr/bin/env python3
"""Tiny expression language interpreter."""


class TokenizeError(Exception):
    pass


class ParseError(Exception):
    pass


class EvalError(Exception):
    pass


def tokenize(src):
    tokens = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        if c in ' \t\n\r':
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and src[j].isdigit():
                j += 1
            tokens.append(('NUM', src[i:j]))
            i = j
            continue
        if c.isalpha() or c == '_':
            j = i
            while j < n and (src[j].isalnum() or src[j] == '_'):
                j += 1
            tokens.append(('NAME', src[i:j]))
            i = j
            continue
        if c == '*':
            if i + 1 < n and src[i + 1] == '*':
                tokens.append(('OP', '**'))
                i += 2
            else:
                tokens.append(('OP', '*'))
                i += 1
            continue
        if c == '/':
            if i + 1 < n and src[i + 1] == '/':
                tokens.append(('OP', '//'))
                i += 2
            else:
                raise TokenizeError("single slash")
            continue
        if c in '+-%':
            tokens.append(('OP', c))
            i += 1
            continue
        if c == '(':
            tokens.append(('LP', '('))
            i += 1
            continue
        if c == ')':
            tokens.append(('RP', ')'))
            i += 1
            continue
        if c == '=':
            tokens.append(('EQ', '='))
            i += 1
            continue
        if c == ';':
            tokens.append(('SEMI', ';'))
            i += 1
            continue
        raise TokenizeError("unknown char: %r" % c)
    return tokens


# AST node types represented as tuples:
# ('num', int)
# ('var', name)
# ('neg', expr)
# ('bin', op, left, right)


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def next(self):
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def at_end(self):
        return self.pos >= len(self.tokens)

    # expr := add
    def parse_expr(self):
        return self.parse_add()

    def parse_add(self):
        left = self.parse_mul()
        while True:
            t = self.peek()
            if t is not None and t[0] == 'OP' and t[1] in ('+', '-'):
                self.next()
                right = self.parse_mul()
                left = ('bin', t[1], left, right)
            else:
                break
        return left

    def parse_mul(self):
        left = self.parse_unary()
        while True:
            t = self.peek()
            if t is not None and t[0] == 'OP' and t[1] in ('*', '//', '%'):
                self.next()
                right = self.parse_unary()
                left = ('bin', t[1], left, right)
            else:
                break
        return left

    def parse_unary(self):
        t = self.peek()
        if t is not None and t[0] == 'OP' and t[1] == '-':
            self.next()
            operand = self.parse_unary()
            return ('neg', operand)
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        t = self.peek()
        if t is not None and t[0] == 'OP' and t[1] == '**':
            self.next()
            # right operand: unary (allows -) then power right-assoc
            exp = self.parse_unary()
            return ('bin', '**', base, exp)
        return base

    def parse_atom(self):
        t = self.peek()
        if t is None:
            raise ParseError("unexpected end")
        if t[0] == 'NUM':
            self.next()
            return ('num', int(t[1]))
        if t[0] == 'NAME':
            self.next()
            return ('var', t[1])
        if t[0] == 'LP':
            self.next()
            inner = self.parse_expr()
            nt = self.peek()
            if nt is None or nt[0] != 'RP':
                raise ParseError("expected )")
            self.next()
            return inner
        raise ParseError("unexpected token: %r" % (t,))


def parse_statements(tokens):
    # split by SEMI at top level (semicolons never appear inside expressions)
    statements = []
    cur = []
    for t in tokens:
        if t[0] == 'SEMI':
            statements.append(cur)
            cur = []
        else:
            cur.append(t)
    statements.append(cur)
    # each element is a list of tokens (may be empty)
    result = []
    for stmt_tokens in statements:
        if len(stmt_tokens) == 0:
            continue  # empty statement (skip)
        result.append(parse_one_statement(stmt_tokens))
    return result


def parse_one_statement(stmt_tokens):
    # Detect assignment: NAME = ...  where the '=' is the second token
    # Assignment target must be a bare NAME.
    # Find first EQ token position.
    eq_index = None
    for idx, t in enumerate(stmt_tokens):
        if t[0] == 'EQ':
            eq_index = idx
            break
    if eq_index is not None:
        # everything before eq_index must be exactly a single NAME
        lhs = stmt_tokens[:eq_index]
        rhs = stmt_tokens[eq_index + 1:]
        if len(lhs) != 1 or lhs[0][0] != 'NAME':
            raise ParseError("invalid assignment target")
        if len(rhs) == 0:
            raise ParseError("empty rhs")
        # rhs must not contain another EQ
        for t in rhs:
            if t[0] == 'EQ':
                raise ParseError("multiple =")
        p = Parser(rhs)
        expr = p.parse_expr()
        if not p.at_end():
            raise ParseError("trailing tokens in rhs")
        return ('assign', lhs[0][1], expr)
    else:
        # bare expression
        p = Parser(stmt_tokens)
        expr = p.parse_expr()
        if not p.at_end():
            raise ParseError("trailing tokens")
        return ('expr', expr)


def eval_expr(node, env):
    kind = node[0]
    if kind == 'num':
        return node[1]
    if kind == 'var':
        name = node[1]
        if name not in env:
            raise EvalError("undefined variable: %s" % name)
        return env[name]
    if kind == 'neg':
        return -eval_expr(node[1], env)
    if kind == 'bin':
        op = node[1]
        left = eval_expr(node[2], env)
        right = eval_expr(node[3], env)
        if op == '+':
            return left + right
        if op == '-':
            return left - right
        if op == '*':
            return left * right
        if op == '//':
            if right == 0:
                raise EvalError("division by zero")
            return left // right
        if op == '%':
            if right == 0:
                raise EvalError("modulo by zero")
            return left % right
        if op == '**':
            if right < 0:
                # negative exponent would produce non-int; treat as error
                raise EvalError("negative exponent")
            return left ** right
        raise EvalError("unknown op")
    raise EvalError("unknown node")


def run_program(src):
    if not isinstance(src, str):
        return None
    try:
        tokens = tokenize(src)
    except TokenizeError:
        return None
    try:
        statements = parse_statements(tokens)
    except ParseError:
        return None
    env = {}
    try:
        for stmt in statements:
            if stmt[0] == 'assign':
                name = stmt[1]
                val = eval_expr(stmt[2], env)
                if not isinstance(val, int):
                    return None
                env[name] = val
            elif stmt[0] == 'expr':
                val = eval_expr(stmt[1], env)
                if not isinstance(val, int):
                    return None
            else:
                return None
    except EvalError:
        return None
    return env


if __name__ == '__main__':
    tests = [
        "a = 2**3**2; b = a + 1",
        "x = -3; y = 2*-3; z = --2",
        "",
        "  ; ; ",
        "1 = 2",
        "a+b = 3",
        "c",
        "1 // 0",
        "(",
        "2 3",
    ]
    for t in tests:
        print(repr(t), "->", run_program(t))

