def run_program(src: str) -> dict | None:
    class _Invalid(Exception):
        pass

    try:
        tokens = []
        i = 0
        n = len(src)

        while i < n:
            c = src[i]

            if c in " \t\n":
                i += 1
                continue

            if "0" <= c <= "9":
                start = i
                i += 1
                while i < n and "0" <= src[i] <= "9":
                    i += 1
                tokens.append(("INT", src[start:i]))
                continue

            if ("A" <= c <= "Z") or ("a" <= c <= "z") or c == "_":
                start = i
                i += 1
                while i < n:
                    ch = src[i]
                    if (
                        ("A" <= ch <= "Z")
                        or ("a" <= ch <= "z")
                        or ("0" <= ch <= "9")
                        or ch == "_"
                    ):
                        i += 1
                    else:
                        break
                tokens.append(("NAME", src[start:i]))
                continue

            if c == "/" and i + 1 < n and src[i + 1] == "/":
                tokens.append(("//", None))
                i += 2
                continue

            if c == "*" and i + 1 < n and src[i + 1] == "*":
                tokens.append(("**", None))
                i += 2
                continue

            if c in ";=+-*%()":
                tokens.append((c, None))
                i += 1
                continue

            raise _Invalid()

        tokens.append(("EOF", None))
        env = {}

        class _Parser:
            def __init__(self):
                self.pos = 0

            def kind(self):
                return tokens[self.pos][0]

            def take(self, kind):
                if self.kind() != kind:
                    raise _Invalid()
                value = tokens[self.pos][1]
                self.pos += 1
                return value

            def parse_integer(self, text):
                value = 0
                for ch in text:
                    value = value * 10 + (ord(ch) - ord("0"))
                return value

            def parse_expression(self):
                return self.parse_additive()

            def parse_additive(self):
                value = self.parse_multiplicative()
                while self.kind() in ("+", "-"):
                    op = self.kind()
                    self.pos += 1
                    right = self.parse_multiplicative()
                    if op == "+":
                        value = value + right
                    else:
                        value = value - right
                return value

            def parse_multiplicative(self):
                value = self.parse_unary()
                while self.kind() in ("*", "//", "%"):
                    op = self.kind()
                    self.pos += 1
                    right = self.parse_unary()
                    if op == "*":
                        value = value * right
                    elif op == "//":
                        if right == 0:
                            raise _Invalid()
                        value = value // right
                    else:
                        if right == 0:
                            raise _Invalid()
                        value = value % right
                return value

            def parse_unary(self):
                if self.kind() == "-":
                    self.pos += 1
                    return -self.parse_unary()
                return self.parse_power()

            def parse_power(self):
                value = self.parse_atom()
                if self.kind() == "**":
                    self.pos += 1
                    exponent = self.parse_unary()
                    if exponent < 0:
                        raise _Invalid()
                    value = pow(value, exponent)
                return value

            def parse_atom(self):
                kind = self.kind()

                if kind == "INT":
                    text = self.take("INT")
                    return self.parse_integer(text)

                if kind == "NAME":
                    name = self.take("NAME")
                    if name not in env:
                        raise _Invalid()
                    return env[name]

                if kind == "(":
                    self.pos += 1
                    value = self.parse_expression()
                    self.take(")")
                    return value

                raise _Invalid()

            def at_statement_end(self):
                return self.kind() in (";", "EOF")

            def parse_program(self):
                while self.kind() != "EOF":
                    if self.kind() == ";":
                        self.pos += 1
                        continue

                    if (
                        self.kind() == "NAME"
                        and tokens[self.pos + 1][0] == "="
                    ):
                        name = tokens[self.pos][1]
                        self.pos += 2
                        value = self.parse_expression()
                        if not self.at_statement_end():
                            raise _Invalid()
                        env[name] = value
                    else:
                        self.parse_expression()
                        if not self.at_statement_end():
                            raise _Invalid()

                    if self.kind() == ";":
                        self.pos += 1

                return env

        return _Parser().parse_program()

    except Exception:
        return None

