"""RFC-4180-style CSV parser implemented without the csv module."""


def parse_csv(text: str) -> list[list[str]]:
    if text == "":
        return []

    records: list[list[str]] = []
    field_chars: list[str] = []
    fields: list[str] = []
    i = 0
    n = len(text)

    def end_field():
        fields.append("".join(field_chars))
        field_chars.clear()

    def end_record():
        end_field()
        records.append(fields.copy())
        fields.clear()

    while i < n:
        c = text[i]

        if c == '"':
            # Quoted field
            i += 1
            while i < n:
                ch = text[i]
                if ch == '"':
                    if i + 1 < n and text[i + 1] == '"':
                        field_chars.append('"')
                        i += 2
                    else:
                        # closing quote
                        i += 1
                        break
                else:
                    field_chars.append(ch)
                    i += 1
            # After closing quote, lenient: append literal content until sep
            while i < n:
                ch = text[i]
                if ch == ',':
                    break
                if ch == '\n':
                    break
                if ch == '\r':
                    break
                if ch == '"':
                    # start of another quoted segment; handle inline
                    i += 1
                    while i < n:
                        c2 = text[i]
                        if c2 == '"':
                            if i + 1 < n and text[i + 1] == '"':
                                field_chars.append('"')
                                i += 2
                            else:
                                i += 1
                                break
                        else:
                            field_chars.append(c2)
                            i += 1
                    continue
                field_chars.append(ch)
                i += 1
            # now at comma, separator, or end
            if i < n:
                sep = text[i]
                if sep == ',':
                    end_field()
                    i += 1
                elif sep == '\r':
                    end_record()
                    if i + 1 < n and text[i + 1] == '\n':
                        i += 2
                    else:
                        i += 1
                elif sep == '\n':
                    end_record()
                    i += 1
            else:
                # end of input
                end_record()

        elif c == ',':
            end_field()
            i += 1

        elif c == '\r':
            end_record()
            if i + 1 < n and text[i + 1] == '\n':
                i += 2
            else:
                i += 1

        elif c == '\n':
            end_record()
            i += 1

        else:
            field_chars.append(c)
            i += 1

    # Handle trailing content not terminated by a record separator.
    if field_chars or fields:
        end_record()

    return records


if __name__ == "__main__":
    tests = [
        ("", []),
        ("a,b\n", [["a", "b"]]),
        ("a,b\r\nc,d", [["a", "b"], ["c", "d"]]),
        ("a,\n", [["a", ""]]),
        ("x\n\ny", [["x"], [""], ["y"]]),
        ('"a"b', [["ab"]]),
        ('"he said ""hi""",x', [['he said "hi"', "x"]]),
        ('"unclosed', [["unclosed"]]),
        ('"multi\nline",z', [["multi\nline", "z"]]),
        (" a , b ", [[" a ", " b "]]),
    ]
    for src, expected in tests:
        got = parse_csv(src)
        status = "OK" if got == expected else "FAIL"
        print(f"{status}: {src!r} -> {got!r}")

