"""Semantic Versioning 2.0.0 validation and precedence comparison."""

__all__ = ("is_valid", "compare")


def _is_ascii_digits(value: str) -> bool:
    if not value:
        return False
    for char in value:
        if char < "0" or char > "9":
            return False
    return True


def _is_identifier(value: str) -> bool:
    if not value:
        return False
    for char in value:
        if not (
            "0" <= char <= "9"
            or "A" <= char <= "Z"
            or "a" <= char <= "z"
            or char == "-"
        ):
            return False
    return True


def _parse(value: str):
    if not isinstance(value, str):
        return None

    build_parts = str.split(value, "+")
    if len(build_parts) > 2:
        return None

    main = build_parts[0]
    if len(build_parts) == 2:
        build = build_parts[1]
        identifiers = str.split(build, ".")
        for identifier in identifiers:
            if not _is_identifier(identifier):
                return None

    prerelease_parts = str.split(main, "-", 1)
    core = prerelease_parts[0]
    prerelease = None

    if len(prerelease_parts) == 2:
        prerelease_text = prerelease_parts[1]
        identifiers = str.split(prerelease_text, ".")
        for identifier in identifiers:
            if not _is_identifier(identifier):
                return None
            if (
                _is_ascii_digits(identifier)
                and len(identifier) > 1
                and identifier[0] == "0"
            ):
                return None
        prerelease = tuple(identifiers)

    core_parts = str.split(core, ".")
    if len(core_parts) != 3:
        return None

    for identifier in core_parts:
        if not _is_ascii_digits(identifier):
            return None
        if len(identifier) > 1 and identifier[0] == "0":
            return None

    return tuple(core_parts), prerelease


def _safe_parse(value):
    try:
        return _parse(value)
    except BaseException:
        return None


def _compare_numeric(left: str, right: str) -> int:
    if len(left) < len(right):
        return -1
    if len(left) > len(right):
        return 1
    if left < right:
        return -1
    if left > right:
        return 1
    return 0


def is_valid(v: str) -> bool:
    """Return whether v exactly matches the Semantic Versioning 2.0.0 grammar."""
    return _safe_parse(v) is not None


def compare(a: str, b: str) -> int:
    """Compare two valid semantic versions by SemVer precedence."""
    parsed_a = _safe_parse(a)
    parsed_b = _safe_parse(b)

    if parsed_a is None or parsed_b is None:
        raise ValueError("invalid semantic version")

    core_a, prerelease_a = parsed_a
    core_b, prerelease_b = parsed_b

    for identifier_a, identifier_b in zip(core_a, core_b):
        result = _compare_numeric(identifier_a, identifier_b)
        if result:
            return result

    if prerelease_a is None:
        return 0 if prerelease_b is None else 1
    if prerelease_b is None:
        return -1

    common_length = min(len(prerelease_a), len(prerelease_b))
    for index in range(common_length):
        identifier_a = prerelease_a[index]
        identifier_b = prerelease_b[index]

        if identifier_a == identifier_b:
            continue

        numeric_a = _is_ascii_digits(identifier_a)
        numeric_b = _is_ascii_digits(identifier_b)

        if numeric_a and numeric_b:
            result = _compare_numeric(identifier_a, identifier_b)
            if result:
                return result
        elif numeric_a:
            return -1
        elif numeric_b:
            return 1
        elif identifier_a < identifier_b:
            return -1
        else:
            return 1

    if len(prerelease_a) < len(prerelease_b):
        return -1
    if len(prerelease_a) > len(prerelease_b):
        return 1
    return 0

