"""Semantic Versioning 2.0.0 validity and precedence."""


def _is_numeric_no_leading_zero(s: str) -> bool:
    if not s or not s.isdigit():
        return False
    if len(s) > 1 and s[0] == '0':
        return False
    return True


def _is_valid_build_id(s: str) -> bool:
    if not s:
        return False
    return all(c.isdigit() or c.isalpha() or c == '-' for c in s)


def _is_valid_prerelease_id(s: str) -> bool:
    if not s:
        return False
    if not all(c.isdigit() or c.isalpha() or c == '-' for c in s):
        return False
    # if all digits, must have no leading zero
    if s.isdigit():
        return _is_numeric_no_leading_zero(s)
    return True


def _parse(v: str):
    """Parse into (major, minor, patch, prerelease_ids_or_None, build_or_None).
    Returns None if invalid."""
    if not isinstance(v, str):
        return None

    build = None
    plus = v.find('+')
    if plus != -1:
        build_str = v[plus + 1:]
        v = v[:plus]
        build_ids = build_str.split('.')
        for b in build_ids:
            if not _is_valid_build_id(b):
                return None
        build = build_ids

    prerelease = None
    dash = v.find('-')
    if dash != -1:
        pre_str = v[dash + 1:]
        v = v[:dash]
        pre_ids = pre_str.split('.')
        for p in pre_ids:
            if not _is_valid_prerelease_id(p):
                return None
        prerelease = pre_ids

    parts = v.split('.')
    if len(parts) != 3:
        return None
    for p in parts:
        if not _is_numeric_no_leading_zero(p):
            return None
    major, minor, patch = (int(parts[0]), int(parts[1]), int(parts[2]))

    return (major, minor, patch, prerelease, build)


def is_valid(v: str) -> bool:
    return _parse(v) is not None


def _cmp_int(a: int, b: int) -> int:
    if a < b:
        return -1
    if a > b:
        return 1
    return 0


def _cmp_pre_id(a: str, b: str) -> int:
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        return _cmp_int(int(a), int(b))
    if a_num and not b_num:
        return -1
    if b_num and not a_num:
        return 1
    # both alphanumeric, ASCII lexical
    if a < b:
        return -1
    if a > b:
        return 1
    return 0


def compare(a: str, b: str) -> int:
    pa = _parse(a)
    pb = _parse(b)
    if pa is None or pb is None:
        raise ValueError("invalid version string")

    for i in range(3):
        c = _cmp_int(pa[i], pb[i])
        if c != 0:
            return c

    pre_a = pa[3]
    pre_b = pb[3]

    # no prerelease has higher precedence
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    n = min(len(pre_a), len(pre_b))
    for i in range(n):
        c = _cmp_pre_id(pre_a[i], pre_b[i])
        if c != 0:
            return c

    return _cmp_int(len(pre_a), len(pre_b))

