_DIGITS = frozenset("0123456789")
_IDENTIFIER_CHARS = frozenset(
    "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-"
)


def _is_numeric_identifier(value: str) -> bool:
    return bool(value) and all(char in _DIGITS for char in value)


def _is_valid_numeric(value: str) -> bool:
    return bool(value) and all(char in _DIGITS for char in value) and (
        value == "0" or value[0] != "0"
    )


def _is_valid_core(value: str) -> bool:
    return _is_valid_numeric(value)


def _is_valid_prerelease_identifier(value: str) -> bool:
    if not value or not all(char in _IDENTIFIER_CHARS for char in value):
        return False
    if _is_numeric_identifier(value):
        return _is_valid_numeric(value)
    return True


def _is_valid_build_identifier(value: str) -> bool:
    return bool(value) and all(char in _IDENTIFIER_CHARS for char in value)


def _parse(value: str):
    if not isinstance(value, str):
        return None

    if value.count("+") > 1:
        return None

    if "+" in value:
        main, build = value.split("+", 1)
        build_parts = build.split(".")
        if not all(_is_valid_build_identifier(part) for part in build_parts):
            return None
    else:
        main = value

    if main.count("-") > 1:
        return None

    if "-" in main:
        core_text, prerelease_text = main.split("-", 1)
        prerelease_parts = prerelease_text.split(".")
        if not all(
            _is_valid_prerelease_identifier(part) for part in prerelease_parts
        ):
            return None
    else:
        core_text = main
        prerelease_parts = None

    core_parts = core_text.split(".")
    if len(core_parts) != 3:
        return None
    if not all(_is_valid_core(part) for part in core_parts):
        return None

    return core_parts[0], core_parts[1], core_parts[2], prerelease_parts


def is_valid(v: str) -> bool:
    """Return whether v is a valid Semantic Version 2.0.0 string."""
    return _parse(v) is not None


def _compare_numeric_strings(left: str, right: str) -> int:
    left = left.lstrip("0") or "0"
    right = right.lstrip("0") or "0"

    if len(left) < len(right):
        return -1
    if len(left) > len(right):
        return 1
    if left < right:
        return -1
    if left > right:
        return 1
    return 0


def compare(a: str, b: str) -> int:
    """Compare two valid Semantic Versions by precedence."""
    parsed_a = _parse(a)
    parsed_b = _parse(b)

    if parsed_a is None or parsed_b is None:
        raise ValueError("invalid semantic version")

    for index in range(3):
        result = _compare_numeric_strings(parsed_a[index], parsed_b[index])
        if result:
            return result

    pre_a = parsed_a[3]
    pre_b = parsed_b[3]

    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    for identifier_a, identifier_b in zip(pre_a, pre_b):
        numeric_a = _is_numeric_identifier(identifier_a)
        numeric_b = _is_numeric_identifier(identifier_b)

        if numeric_a and numeric_b:
            result = _compare_numeric_strings(identifier_a, identifier_b)
        elif numeric_a and not numeric_b:
            result = -1
        elif not numeric_a and numeric_b:
            result = 1
        elif identifier_a < identifier_b:
            result = -1
        elif identifier_a > identifier_b:
            result = 1
        else:
            result = 0

        if result:
            return result

    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1
    return 0

