"""Semantic Versioning 2.0.0 implementation (stdlib only)."""

__all__ = ["is_valid", "compare"]


# Allowed characters in identifiers: digits, ASCII letters, and hyphen.
_ALLOWED_ID_CHARS = set("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-")


def _is_digits(s: str) -> bool:
    """Return True iff `s` is non-empty and every char is an ASCII digit."""
    if not s:
        return False
    for ch in s:
        if ch < '0' or ch > '9':
            return False
    return True


def _is_valid_numeric_id(s: str) -> bool:
    """A numeric identifier: non-empty digits, no leading zeros unless '0'."""
    if not s:
        return False
    if not _is_digits(s):
        return False
    if len(s) > 1 and s[0] == '0':
        return False
    return True


def _is_valid_alphanumeric_id(s: str) -> bool:
    """An alphanumeric identifier: non-empty, only [0-9A-Za-z-], not numeric (no leading zero)."""
    if not s:
        return False
    for ch in s:
        if ch not in _ALLOWED_ID_CHARS:
            return False
    # If all characters are digits, it must satisfy the numeric no-leading-zeros rule.
    if _is_digits(s):
        if len(s) > 1 and s[0] == '0':
            return False
    return True


def _split_build(v: str):
    """Split off the build metadata after '+'. Returns (rest, build_or_None).

    Build metadata is everything after the first '+'. If a '+' is present
    but no characters follow, that's an invalid build (empty identifier).
    Multiple '+' characters are not allowed by SemVer; only the first splits.
    """
    idx = v.find('+')
    if idx == -1:
        return v, None
    rest = v[:idx]
    build = v[idx + 1:]
    # Per spec, build metadata follows the single '+'; the remaining '+' chars
    # would be part of an identifier and are forbidden by [0-9A-Za-z-].
    # So reject any further '+' in the build portion.
    if '+' in build:
        return None, None
    if not build:
        # Empty build identifier -> invalid.
        return None, None
    return rest, build


def _split_prerelease(v: str):
    """Split off the prerelease after '-'. Returns (core, pre_or_None).

    Only the first '-' introduces the prerelease; subsequent '-' belong to
    identifiers which are allowed to contain '-'. A leading '-' on an empty
    identifier (e.g. '1.0.0-') makes the version invalid.
    """
    idx = v.find('-')
    if idx == -1:
        return v, None
    core = v[:idx]
    pre = v[idx + 1:]
    if not pre:
        return None, None
    return core, pre


def _check_core(core: str):
    """Validate the 'major.minor.patch' portion. Returns (parts, ok)."""
    pieces = core.split('.')
    if len(pieces) != 3:
        return None, False
    parts = []
    for p in pieces:
        if not _is_valid_numeric_id(p):
            return None, False
        parts.append(int(p))
    return parts, True


def _check_idents(blob: str, allow_numeric_no_leading_zero: bool):
    """Check a dot-separated list of identifiers.

    `allow_numeric_no_leading_zero`:
      False -> build-style: any non-empty [0-9A-Za-z-] identifier is fine.
      True  -> prerelease-style: numeric ids must not have leading zeros
               (unless a single '0'); alphanumeric ids are fine as-is and
               may incidentally be all-digit but then must obey the rule.
    Returns list of idents (strings) on success, or None on failure.
    """
    if not blob:
        return None
    idents = blob.split('.')
    for ident in idents:
        if not ident:
            return None
        for ch in ident:
            if ch not in _ALLOWED_ID_CHARS:
                return None
        if allow_numeric_no_leading_zero:
            if not _is_valid_alphanumeric_id(ident):
                return None
        # else: accept as long as chars are allowed and non-empty.
    return idents


def is_valid(v: str) -> bool:
    """Return True iff `v` is a strict SemVer 2.0.0 version string."""
    if not isinstance(v, str) or not v:
        return False

    # Pull off optional build metadata.
    rest, build = _split_build(v)
    if rest is None and build is None and '+' in v:
        return False

    # Pull off optional prerelease.
    core, pre = _split_prerelease(rest)
    if core is None and pre is None and '-' in rest:
        return False

    parts, ok = _check_core(core)
    if not ok:
        return False

    if pre is not None:
        if _check_idents(pre, allow_numeric_no_leading_zero=True) is None:
            return False

    if build is not None:
        if _check_idents(build, allow_numeric_no_leading_zero=False) is None:
            return False

    return True


def _parse(v: str):
    """Parse and validate `v`, returning a tuple usable for comparison.

    Returns a dict-like tuple on success, or None if invalid.
    Layout: (major, minor, patch, has_prerelease: bool, pre_idents: tuple, build_idents: tuple)
    """
    if not isinstance(v, str) or not v:
        return None

    rest, build = _split_build(v)
    if rest is None and build is None and '+' in v:
        return None

    core, pre = _split_prerelease(rest)
    if core is None and pre is None and '-' in rest:
        return None

    parts, ok = _check_core(core)
    if not ok:
        return None

    pre_idents = ()
    has_pre = False
    if pre is not None:
        pre_idents = _check_idents(pre, allow_numeric_no_leading_zero=True)
        if pre_idents is None:
            return None
        has_pre = True

    build_idents = ()
    if build is not None:
        build_idents = _check_idents(build, allow_numeric_no_leading_zero=False)
        if build_idents is None:
            return None

    return (parts[0], parts[1], parts[2], has_pre, pre_idents, build_idents)


def _id_kind(ident: str) -> str:
    """Return 'num' iff `ident` is purely ASCII digits, else 'alphanum'."""
    if _is_digits(ident):
        return 'num'
    return 'alphanum'


def _compare_idents(a: str, b: str) -> int:
    """Compare two prerelease identifiers per SemVer precedence rules."""
    ka = _id_kind(a)
    kb = _id_kind(b)
    if ka == 'num' and kb == 'num':
        # Numeric vs numeric: compare as integers. Use length then lexicographic
        # to avoid int overflow surprises with arbitrarily long digit strings;
        # for valid prerelease numerics there are no leading zeros, so length
        # comparison suffices, and equal lengths means lexicographic works.
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        if a == b:
            return 0
        return -1 if a < b else 1
    if ka == 'num' and kb == 'alphanum':
        return -1
    if ka == 'alphanum' and kb == 'num':
        return 1
    # Both alphanumeric: ASCII lexical compare.
    if a == b:
        return 0
    return -1 if a < b else 1


def _compare_pre(a, b):
    """Compare prerelease identifier tuples; return -1/0/1."""
    n = len(a) if len(a) < len(b) else len(b)
    for i in range(n):
        c = _compare_idents(a[i], b[i])
        if c != 0:
            return c
    if len(a) == len(b):
        return 0
    # Larger set of fields has higher precedence.
    return -1 if len(a) < len(b) else 1


def compare(a: str, b: str) -> int:
    """Compare two SemVer version strings. Returns -1, 0, or 1.

    Raises ValueError if either argument is not a valid SemVer version.
    Build metadata is ignored for precedence.
    """
    pa = _parse(a)
    if pa is None:
        raise ValueError(f"not a valid semantic version: {a!r}")
    pb = _parse(b)
    if pb is None:
        raise ValueError(f"not a valid semantic version: {b!r}")

    am, an, ap, ahas, apre, _abuild = pa
    bm, bn, bp, bhas, bpre, _bbuild = pb

    if am != bm:
        return -1 if am < bm else 1
    if an != bn:
        return -1 if an < bn else 1
    if ap != bp:
        return -1 if ap < bp else 1

    # Major.minor.patch equal. Now handle prerelease precedence.
    if not ahas and not bhas:
        return 0
    if ahas and not bhas:
        # a has prerelease -> lower precedence.
        return -1
    if not ahas and bhas:
        return 1
    # Both have prerelease.
    return _compare_pre(apre, bpre)

