import heapq as _heapq


def toposort(graph: dict) -> list | None:
    """Return the deterministic dependency order, or None if a cycle exists."""
    nodes = set(graph)
    dependencies = {}

    for node, deps in graph.items():
        unique_deps = set(deps)
        dependencies[node] = unique_deps
        nodes.update(unique_deps)

    indegree = {node: 0 for node in nodes}
    dependents = {node: set() for node in nodes}

    for node, deps in dependencies.items():
        indegree[node] = len(deps)
        for dependency in deps:
            dependents[dependency].add(node)

    eligible = [node for node in nodes if indegree[node] == 0]
    _heapq.heapify(eligible)

    order = []

    while eligible:
        node = _heapq.heappop(eligible)
        order.append(node)

        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                _heapq.heappush(eligible, dependent)

    return order if len(order) == len(nodes) else None

