"""Deterministic topological sort by dependency order."""

import heapq


def toposort(graph: dict) -> list | None:
    # Collect all nodes (keys and dependencies).
    nodes = set()
    deps = {}
    for node, dependencies in graph.items():
        nodes.add(node)
        dset = set()
        for d in dependencies:
            nodes.add(d)
            dset.add(d)
        deps[node] = dset

    # Ensure every node has a dependency set.
    for n in nodes:
        if n not in deps:
            deps[n] = set()

    # dependents: for each node, who depends on it.
    dependents = {n: [] for n in nodes}
    indegree = {n: 0 for n in nodes}
    for node, dset in deps.items():
        indegree[node] = len(dset)
        for d in dset:
            dependents[d].append(node)

    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        n = heapq.heappop(heap)
        result.append(n)
        for m in dependents[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(heap, m)

    if len(result) != len(nodes):
        return None
    return result

