def toposort(graph: dict) -> list | None:
    dependencies = {}
    nodes = set()

    for node, required in graph.items():
        nodes.add(node)
        dependencies.setdefault(node, set())
        for dependency in required:
            nodes.add(dependency)
            dependencies.setdefault(dependency, set())
            dependencies[node].add(dependency)

    emitted = set()
    order = []

    while len(order) < len(nodes):
        eligible = [
            node
            for node in nodes
            if node not in emitted and dependencies[node].issubset(emitted)
        ]

        if not eligible:
            return None

        node = min(eligible)
        emitted.add(node)
        order.append(node)

    return order

