"""Strict canonicalization of absolute HTTP and HTTPS URLs."""

_HEX = frozenset("0123456789abcdefABCDEF")
_UNRESERVED = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~"
)
_SUBDELIMS = frozenset("!$&'()*+,;=")
_HOST_CHARS = _UNRESERVED | _SUBDELIMS
_PCHAR_CHARS = _UNRESERVED | _SUBDELIMS | frozenset(":@")
_PATH_CHARS = _PCHAR_CHARS | frozenset("/")
_QUERY_FRAGMENT_CHARS = _PCHAR_CHARS | frozenset("/?")


def _normalize_component(
    value: str, allowed: frozenset[str], *, lowercase: bool = False
) -> str | None:
    """Validate an ASCII URI component and uppercase percent-escape hex digits."""
    output: list[str] = []
    index = 0

    while index < len(value):
        char = value[index]

        if char == "%":
            if (
                index + 2 >= len(value)
                or value[index + 1] not in _HEX
                or value[index + 2] not in _HEX
            ):
                return None
            output.append("%")
            output.append(value[index + 1].upper())
            output.append(value[index + 2].upper())
            index += 3
            continue

        if char not in allowed:
            return None

        output.append(char.lower() if lowercase else char)
        index += 1

    return "".join(output)


def _normalize_path(path: str) -> str | None:
    if not path:
        return "/"
    if not path.startswith("/"):
        return None

    normalized = _normalize_component(path, _PATH_CHARS)
    if normalized is None:
        return None

    original_segments = normalized.split("/")
    trailing_directory = (
        normalized.endswith("/")
        or original_segments[-1] == "."
        or original_segments[-1] == ".."
    )

    resolved: list[str] = []
    for segment in original_segments:
        if segment == "" or segment == ".":
            continue
        if segment == "..":
            if resolved:
                resolved.pop()
            continue
        resolved.append(segment)

    result = "/" + "/".join(resolved)
    if trailing_directory and result != "/":
        result += "/"
    return result


def _canonicalize_impl(url: str) -> str | None:
    delimiter = url.find("://")
    if delimiter < 0:
        return None

    scheme = url[:delimiter].lower()
    if scheme not in ("http", "https"):
        return None

    remainder = url[delimiter + 3 :]

    authority_end = len(remainder)
    for marker in "/?#":
        position = remainder.find(marker)
        if position >= 0 and position < authority_end:
            authority_end = position

    authority = remainder[:authority_end]
    suffix = remainder[authority_end:]

    if not authority or "@" in authority:
        return None

    # IPv6 literals are outside the accepted host grammar, so an authority can
    # contain at most one colon, used exclusively as the port separator.
    if authority.count(":") > 1:
        return None

    if ":" in authority:
        host_text, port_text = authority.rsplit(":", 1)
        if not host_text or not port_text or not port_text.isascii():
            return None
        if not all("0" <= char <= "9" for char in port_text):
            return None

        significant_port = port_text.lstrip("0")
        if not significant_port:
            return None
        if len(significant_port) > 5:
            return None

        port_number = int(significant_port)
        if not 1 <= port_number <= 65535:
            return None

        default_port = 80 if scheme == "http" else 443
        port = "" if port_number == default_port else ":" + str(port_number)
    else:
        host_text = authority
        port = ""

    host = _normalize_component(host_text, _HOST_CHARS, lowercase=True)
    if host is None or not host:
        return None

    fragment_text: str | None = None
    hash_position = suffix.find("#")
    if hash_position >= 0:
        fragment_text = suffix[hash_position + 1 :]
        suffix = suffix[:hash_position]

    query_text: str | None = None
    query_position = suffix.find("?")
    if query_position >= 0:
        query_text = suffix[query_position + 1 :]
        path_text = suffix[:query_position]
    else:
        path_text = suffix

    path = _normalize_path(path_text)
    if path is None:
        return None

    query = ""
    if query_text:
        normalized_query = _normalize_component(
            query_text, _QUERY_FRAGMENT_CHARS
        )
        if normalized_query is None:
            return None
        query = "?" + normalized_query

    fragment = ""
    if fragment_text:
        normalized_fragment = _normalize_component(
            fragment_text, _QUERY_FRAGMENT_CHARS
        )
        if normalized_fragment is None:
            return None
        fragment = "#" + normalized_fragment

    return scheme + "://" + host + port + path + query + fragment


def canonicalize(url: str) -> str | None:
    """Return the canonical absolute HTTP(S) URL, or None if it is unacceptable."""
    try:
        if not isinstance(url, str):
            return None
        return _canonicalize_impl(url)
    except Exception:
        return None

