        )
        subdelims = "!$&'()*+,;="
        allowed = unreserved + subdelims + ":@"
        if allow_slash:
            allowed += "/"
        if allow_question:
            allowed += "?"
        i = 0
        while i < len(value):
            ch = value[i]
            if ch == "%":
                if i + 2 >= len(value):
                    return False
                if (
                    value[i + 1] not in "0123456789abcdefABCDEF"
                    or value[i + 2] not in "0123456789abcdefABCDEF"
                ):
                    return False
                i += 3
                continue
            if ch not in allowed:
                return False
            i += 1
        return True

    if not isinstance(url, str):
        return None

    lowered = url.lower()
    if lowered.startswith("http://"):
        scheme = "http"
        start = 7
        default_port = 80
    elif lowered.startswith("https://"):
        scheme = "https"
        start = 8
        default_port = 443
    else:
        return None

    # Reject control characters and non-ASCII URL syntax conservatively.
    for ch in url:
        if ord(ch) < 0x20 or ord(ch) == 0x7F or ord(ch) > 0x7F:
            return None

    remainder = url[start:]

    authority_end = len(remainder)
    for delimiter in "/?#":
        pos = remainder.find(delimiter)
        if pos != -1 and pos < authority_end:
            authority_end = pos

    authority = remainder[:authority_end]
    tail = remainder[authority_end:]

    if not authority or "@" in authority:
        return None

    if authority.count(":") > 1:
        return None

    if ":" in authority:
        host, port_text = authority.split(":", 1)
        if not port_text or not port_text.isdigit():
            return None

        stripped = port_text.lstrip("0")
        if not stripped:
            return None
        if len(stripped) > 5:
            return None
        port_value = int(stripped)
        if port_value < 1 or port_value > 65535:
            return None

        port_suffix = "" if port_value == default_port else ":" + str(port_value)
    else:
        host = authority
        port_suffix = ""

    if not host:
        return None
    if host.startswith("[") or host.endswith("]"):
        return None

    # Accept ordinary ASCII DNS-style registered names. A trailing dot is
    # allowed for a fully-qualified name, but other empty labels are not.
    host_lower = host.lower()
    if host_lower.endswith("."):
        label_part = host_lower[:-1]
    else:
        label_part = host_lower

    if not label_part:
        return None

    labels = label_part.split(".")
    for label in labels:
        if not label or len(label) > 63:
            return None
        if label[0] == "-" or label[-1] == "-":
            return None
        for ch in label:
            if not ("a" <= ch <= "z" or "0" <= ch <= "9" or ch == "-"):
                return None

    # Reject malformed dotted-decimal-looking hosts rather than treating them
    # as names.
    if len(labels) == 4 and all(label.isdigit() for label in labels):
        if any(int(label) > 255 for label in labels):
            return None

    if tail:
        query_pos = tail.find("?")
        fragment_pos = tail.find("#")

        cut = len(tail)
        if query_pos != -1 and query_pos < cut:
            cut = query_pos
        if fragment_pos != -1 and fragment_pos < cut:
            cut = fragment_pos

        path = tail[:cut]
        remainder_tail = tail[cut:]
    else:
        path = ""
        remainder_tail = ""

    if path and not path.startswith("/"):
        return None
    if not valid_component(path, allow_slash=True, allow_question=False):
        return None

    query = None
    fragment = None

    if remainder_tail.startswith("?"):
        hash_pos = remainder_tail.find("#", 1)
        if hash_pos == -1:
            query = remainder_tail[1:]
            remainder_tail = ""
        else:
            query = remainder_tail[1:hash_pos]
            remainder_tail = remainder_tail[hash_pos:]

    if remainder_tail.startswith("#"):
        fragment = remainder_tail[1:]
        remainder_tail = ""

    if remainder_tail:
        return None

    if query is not None:
        if not valid_component(query, allow_slash=True, allow_question=True):
            return None
        query = uppercase_escapes(query)
        if query is None:
            return None
        if query == "":
            query = None

    if fragment is not None:
        if not valid_component(fragment, allow_slash=True, allow_question=True):
            return None
        fragment = uppercase_escapes(fragment)
        if fragment is None:
            return None
        if fragment == "":
            fragment = None

    normalized_path = uppercase_escapes(path)
    if normalized_path is None:
        return None

    if not normalized_path:
        canonical_path = "/"
    else:
        parts = normalized_path.split("/")
        segments = []
        trailing_directory = normalized_path.endswith("/")

        for segment in parts:
            if segment == "":
                continue
            if segment == ".":
                trailing_directory = True
            elif segment == "..":
                if segments:
                    segments.pop()
                trailing_directory = True
            else:
                segments.append(segment)

        canonical_path = "/" + "/".join(segments)
        if trailing_directory and canonical_path != "/":
            canonical_path += "/"

    result = scheme + "://" + host_lower + port_suffix + canonical_path
    if query is not None:
        result += "?" + query
    if fragment is not None:
        result += "#" + fragment
    return result

#!/usr/bin/env python3
def canonicalize(url):
    if not isinstance(url, str):
        return None
    s = url
    # Find scheme
    scheme_end = s.find(':')
    if scheme_end <= 0:
        return None
    scheme = s[:scheme_end].lower()
    if scheme not in ('http', 'https'):
        return None
    rest = s[scheme_end+1:]
    # Must start with "//" after scheme colon
    if not rest.startswith('//'):
        return None
    rest = rest[2:]
    # Split off fragment
    frag = None
    hash_idx = rest.find('#')
    if hash_idx != -1:
        frag_part = rest[hash_idx+1:]
        frag = frag_part  # may be empty string
        rest = rest[:hash_idx]
    # Split off query
    query = None
    q_idx = rest.find('?')
    if q_idx != -1:
        query_part = rest[q_idx+1:]
        query = query_part
        rest = rest[:q_idx]
    # Now rest is authority + path
    # Find first '/' for path start
    path_idx = rest.find('/')
    if path_idx == -1:
        authority = rest
        path = ''
    else:
        authority = rest[:path_idx]
        path = rest[path_idx:]
    # Parse host and port from authority
    # Reject userinfo (any '@')
    if '@' in authority:
        return None
    if not authority:
        return None
    # Port
    port_str = None
    host = authority
    # IPv6 in brackets? Spec says "registered name or IPv4", so reject IPv6 literals.
    if host.startswith('['):
        return None
    # Find last colon - if multiple colons, it's not IPv4 (which we only accept)
    colon_idx = host.rfind(':')
    if colon_idx != -1:
        port_part = host[colon_idx+1:]
        host = host[:colon_idx]
        # Validate port is all digits
        if not port_part or not port_part.isdigit():
            return None
        port_str = port_part
    # Validate host is non-empty
    if not host:
        return None
    # Lowercase host
    host = host.lower()
    # Validate host: registered name or IPv4
    if not _is_valid_host(host):
        return None
    # Validate port range
    if port_str is not None:
        # Strip leading zeros for comparison, but treat all-digit string
        # Convert to int
        try:
            port_num = int(port_str)
        except ValueError:
            return None
        if port_num < 1 or port_num > 65535:
            return None
        # Check if default port
        default = 80 if scheme == 'http' else 443
        if port_num == default:
            port_out = ''
        else:
            port_out = ':' + str(port_num)
    else:
        port_out = ''
    # Normalize path
    if path == '':
        path = '/'
    norm_path = _normalize_path(path)
    # Uppercase percent-encoding hex in path
    norm_path = _uppercase_percent(norm_path)
    # Uppercase percent-encoding hex in query
    if query is not None:
        query_out = _uppercase_percent(query)
        if query_out == '':
            query_final = ''
        else:
            query_final = '?' + query_out
    else:
        query_final = ''
    # Fragment
    if frag is not None:
        frag_out = _uppercase_percent(frag)
        if frag_out == '':
            frag_final = ''
        else:
            frag_final = '#' + frag_out
    else:
        frag_final = ''
    return scheme + '://' + host + port_out + norm_path + query_final + frag_final

def _is_valid_host(host):
    if not host:
        return False
    # Reject empty labels, leading/trailing hyphens, etc.
    # Registered name: labels of letters/digits/hyphens, separated by dots
    # IPv4: four dot-separated decimals 0-255
    # Try IPv4 first
    parts = host.split('.')
    if len(parts) == 4 and all(p.isdigit() for p in parts):
        try:
            nums = [int(p) for p in parts]
            if all(0 <= n <= 255 for n in nums):
                # Check for leading zeros - reject "01" style (lenient: allow "0" but not "01")
                ok = True
                for p, n in zip(parts, nums):
                    if len(p) > 1 and p[0] == '0':
                        ok = False
                        break
                if ok:
                    return True
        except ValueError:
            pass
    # Registered name validation
    if '.' in host:
        labels = host.split('.')
    else:
        labels = [host]
    for label in labels:
        if not label:
            return False
        if len(label) > 63:
            return False
        # Must not start or end with hyphen
        if label[0] == '-' or label[-1] == '-':
            return False
        for ch in label:
            if not (ch.isalnum() or ch == '-'):
                return False
    # Total length check
    if len(host) > 253:
        return False
    # A single label is technically valid (e.g., "localhost")
    return True

def _normalize_path(path):
    # Collapse multiple slashes first
    # Split by '/'
    # We handle this manually to preserve semantics
    # Actually we need to handle "//" -> "/" collapse
    # Split into segments by '/', then process
    # Leading slash behavior: path starts with '/'
    if not path:
        return '/'
    # Special case: if path starts with '/', we resolve from root
    if path == '/':
        return '/'
    leading_slash = path[0] == '/'
    # Collapse multiple slashes by splitting and rejoining
    parts = path.split('/')
    # parts will have empty strings for consecutive slashes
    # Filter out empty segments, but track trailing slash intent
    segments = []
    for p in parts:
        if p == '':
            continue
        segments.append(p)
    # Now process '.' and '..'
    # Determine if original path ended with '/'
    # Strip leading empty segment if path started with '/' (parts[0] is '')
    # Actually after split('/'), parts[0] is '' for "/foo" and that's filtered above.
    ended_with_slash = path.endswith('/') and len(path) > 1
    # Track whether last meaningful segment was '.' or '..'
    # We need to know if the original LAST segment was "." or ".."
    # Find last non-empty segment in original path
    last_seg_was_dot = False
    last_seg_was_dotdot = False
    # Get original segments (between slashes) preserving order
    orig_segments = [p for p in parts if p != '']
    if orig_segments:
        last = orig_segments[-1]
        if last == '.':
            last_seg_was_dot = True
        elif last == '..':
            last_seg_was_dotdot = True
    # Build stack
    stack = []
    for seg in segments:
        if seg == '.':
            continue  # skip
        elif seg == '..':
            if stack and stack[-1] != '':
                stack.pop()
            # else: pop nothing (clamped at root), but we don't add '..'
        else:
            stack.append(seg)
    # Determine trailing slash:
    # Preserve trailing slash if:
    # - original path ended in "/", OR
    # - original last segment was "." or ".." (resolving to a directory)
    # But if the result is empty (just "/"), don't double-slash
    has_trailing = False
    if ended_with_slash:
        has_trailing = True
    elif last_seg_was_dot or last_seg_was_dotdot:
        # Only add trailing slash if there's something on the stack
        # Actually: "/a/.." -> stack=[], last was '..', but result is "/" (root)
        # "/a/./.." -> stack=[], last is '..', result is "/"
        # "/a/b/.." -> stack=['a'], last is '..', result is "/a/" (directory)
        # "/a/." -> stack=['a'], last is '.', result is "/a/"
        # "/a/b/." -> stack=['a','b'], last is '.', result is "/a/b/"
        # So yes, add trailing slash if last was '.' or '..' and we have non-empty stack
        if stack:
            has_trailing = True
    # Now reconstruct
    if not stack:
        return '/'
    result = '/' + '/'.join(stack)
    if has_trailing:
        result += '/'
    return result

def _uppercase_percent(s):
    # Convert %XY where X,Y are hex to uppercase
    if '%' not in s:
        return s
    result = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch == '%' and i + 2 < n:
            # Need exactly 2 more chars and both hex
            hex_chars = s[i+1:i+3]
            if len(hex_chars) == 2 and _is_hex(hex_chars[0]) and _is_hex(hex_chars[1]):
                result.append('%')
                result.append(hex_chars[0].upper())
                result.append(hex_chars[1].upper())
                i += 3
                continue
        result.append(ch)
        i += 1
    return ''.join(result)

def _is_hex(c):
    return ('0' <= c <= '9') or ('a' <= c <= 'f') or ('A' <= c <= 'F')
